export const meta = {
  name: 'map-uniqueness-assembly-gap',
  description: 'Parallel readers map the exact remaining gap for the RankOneDivisorUniqueness discharge and the downstream endgame',
  phases: [
    { title: 'Map', detail: 'six parallel readers over the AJCR Picard cone' },
  ],
}

phase('Map')

const ROOT = '/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'

const COMMON = `You are mapping Lean 4 code in the project at ${ROOT} (an algebraic-geometry formalization; Lean 4 + mathlib). Work READ-ONLY: do not edit any file. Report exact declaration names, full statements (copy the signature verbatim including hypotheses and instance arguments), file paths, and line numbers. Your final message is consumed by another agent as raw data — be complete and precise, no pleasantries.`

const SCHEMA = {
  type: 'object',
  properties: {
    findings: { type: 'string', description: 'The full structured report: exact signatures, file:line, and analysis' },
    gaps: { type: 'string', description: 'What is MISSING (no existing declaration covers it) relevant to the questions asked' },
  },
  required: ['findings', 'gaps'],
}

const readers = [
  {
    key: 'relpic-T1',
    prompt: `${COMMON}
Read ${ROOT}/AlgebraicJacobian/Picard/RelPicBaseLocalTriviality.lean IN FULL, and ${ROOT}/AlgebraicJacobian/Picard/DivisorFamilyMonoH1.lean IN FULL.
Questions:
1. Exact statements of every public lemma in RelPicBaseLocalTriviality.lean, especially DivFamZarAff.exists_notMem_picClass_map_eq_of_relPicMk_eq and exists_notMem_cechPicMap_eq_of_relPicMk_eq. What exactly do they give: for which prime q, which f not in q, equality of WHAT after base change to Localization.Away f?
2. What is relPicMk / picClass / cechPicClass for a DivFamZarAff family — where defined, and what known lemmas convert between (a) abelDivAffPlus equality of two families and (b) relPicMk / picClass equality? Search the project (grep) for lemmas mentioning both abelDivAffPlus and picClass or relPicMk.
3. What does DivisorFamilyMonoH1.lean provide (all public declarations)?`,
  },
  {
    key: 'locus-presentation',
    prompt: `${COMMON}
Read ${ROOT}/AlgebraicJacobian/Picard/Pic0RankOneLocus.lean (at least all definitions: PicRankOneOpen, picDegLayer, picEtAffineEquiv, PicRankOneLocalPresentation) and ${ROOT}/AlgebraicJacobian/Picard/Pic0RankOnePresentation.lean if it exists; also grep for 'structure PicRankOneLocalPresentation' and 'PicRankOneNativePresentation' definitions and read those definitions fully.
Questions:
1. What EXACTLY is membership lam ∈ (PicRankOneOpen pi).obj (op (overSpec k S))? Unfold the definition chain.
2. What data does a PicRankOneLocalPresentation pi lam carry (fields, the étale/Noetherian carrier, the BasicOpenCocycleDatum inside it, how its cechPicClass relates to lam)?
3. Which existing lemmas produce, from membership lam ∈ PicRankOneOpen, a PicRankOneLocalPresentation or a BasicOpenCocycleDatum near a prime / after localization (Localization.Away)? List producers: PicRankOneNativePresentation.nonempty_of_localPresentations, mem_picRankOneOpen_iff_isSplitWitness, etc. — full signatures.
4. Is there a lemma that from lam ∈ PicRankOneOpen over S produces, for EVERY prime p of S, an f ∉ p and a presentation/datum over Localization.Away f? Exact name or state that it is missing.`,
  },
  {
    key: 'datum-certificates',
    prompt: `${COMMON}
Read the definition of BasicOpenCocycleDatum (grep 'structure BasicOpenCocycleDatum' in ${ROOT}/AlgebraicJacobian and read that file's relevant sections), plus ${ROOT}/AlgebraicJacobian/Picard/Pic0RankOneFamilyCertificates.lean, ${ROOT}/AlgebraicJacobian/Cohomology/RankOneFamilyCertificatesActualDatum.lean and RankOneFamilyCertificatesActualDatumRank.lean if they exist.
Questions:
1. BasicOpenCocycleDatum C B pi: all fields (pieces, unit, index, pointedCover, pieceIndex, sheaf, cechPicClass, component, sectionLocalEquations...). Which of these are data vs propositional?
2. The T5 core theorem AlgebraicGeometry.BasicOpenCocycleDatum.divFamZarAff_eq_of_picClass_eq_cechPicClass (in Picard/Pic0RankOneDivisorUnique.lean) needs: hH1 : Subsingleton (Sheaf.HModule D.sheaf 1), hfin : Module.Finite B (Sheaf.HModule D.sheaf 0), hproj : Module.Projective B (...0), hrank : rankAtStalk = 1 at every prime. Which existing lemmas DISCHARGE those four for the datum of a presentation? Full signatures of e.g. rankAtStalk_hModule_zero_eq_one_of_actualPairH1, RankOneFamilyCertificates.ofActualDatum, subsingleton_datumPair_h1_iff, and any 'Module.Finite'/'Module.Projective' producers for Sheaf.HModule D.sheaf 0. Note any Noetherian hypotheses.
3. For F : DivFamZarAff C B (genus C), what is F.picClass and what lemma relates abelDivAffPlus C B F to F.picClass or to D.cechPicClass? grep for 'picClass' in the Picard directory and list the bridging lemmas with signatures.`,
  },
  {
    key: 'divfam-separated',
    prompt: `${COMMON}
Question: does the project have a ZARISKI LOCAL-TO-GLOBAL EQUALITY (separatedness) principle for DivFamZarAff — i.e. from F, G : DivFamZarAff C A d and a finite family f_i spanning the unit ideal of A (or an étale/faithfully-flat cover) with DivFamZarAff.mapAlgHom (to Localization.Away f_i or the cover carrier) F = ... G for all i, conclude F = G?
Method: read ${ROOT}/AlgebraicJacobian/Picard/DivRepAffFaithfullyFlatDescent.lean IN FULL (especially anything like descent uniqueness / injectivity, DivFamZarAff.exists_descent_of_tensor_eq and neighbours), and grep the whole ${ROOT}/AlgebraicJacobian tree for: 'mapAlgHom_injective', 'eq_of_forall', 'eq_of_localization', 'Away.*eq_of', 'injective.*DivFamZarAff', 'DivFamZarAff.*injective', 'separat'. Also check DivRepAwaySpanGlue*.lean and DivRepClassifyZarAffLocal.lean for span-of-units glue idioms.
Report every candidate with full signature, and if the faithfully-flat descent theorem's uniqueness half already gives injectivity of F ↦ mapAlgHom(cover) F, spell out how (exact statement of the uniqueness clause). Also report the exact definition and location of DivFamZarAff.mapAlgHom and DivFamZarAff.mk_eq_mk_iff.`,
  },
  {
    key: 'endgame-contract',
    prompt: `${COMMON}
Read ${ROOT}/AlgebraicJacobian/Picard/Pic0EndgameContract.lean IN FULL, plus grep for and read the declarations/stubs of: rankOneAbelIso, AbelInverse, pic0_sepClosed_representableBy, pic0_representableBy, JacobianData — including in ${ROOT}/AlgebraicJacobian/Challenge.lean and any Pic0Representability*.lean / JacobianData*.lean files (list the files that exist).
Questions:
1. The exact remaining chain: what statement is pic0_representableBy, what does it consume, and what are the currently-missing named inputs (interfaces/contracts) between canonicalRankOneDivisorOfPresentation and the headline? For each missing piece give the exact Prop/def as stated in the contract file.
2. What is the headline statement in Challenge.lean (JacobianData?) and what does it need?
3. Read ${ROOT}/AlgebraicJacobian/Picard/Pic0RankOneFibrePresentedProducer.lean IN FULL: what do rankOneAbelSigma, PicRankOneFibrePresentationInput, toFibrePresented_of_evaluationDivisorPullback, picRankOneOpen_isOpen_of_evaluationDivisorPullbackFamilies provide, and what remains to instantiate them (the EvaluationDivisorPullback obligations)? What role does RankOneDivisorUniqueness / canonical divisor play in filling PicRankOneFibrePresentationInput?`,
  },
  {
    key: 'pdf-contract-check',
    prompt: `You are auditing plan fidelity for a Lean formalization task. READ-ONLY. Read these two PDFs with the Read tool (they are the binding reviewer documents):
/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge/informal/AJCR_Runs_121_122_123_Supervision_Note_2026-08-07.pdf (read ALL pages)
/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge/informal/Lean_Algebraic_Jacobian_Complete_Execution_Plan.pdf (read the pages that state the FINAL deliverables/headline and any acceptance gates; skim structure first, then read the relevant pages).
Questions:
1. List every ACCEPTANCE GATE / binding requirement the supervision note imposes (the A–F producer contract and anything else: axiom hygiene, root reachability, what counts as fake/smuggled, required endpoints).
2. What exactly do the documents demand for pic0_representableBy and the Jacobian headline (names, statement shape, which project: AJC vs AJCR)?
3. Any requirement that a session could accidentally violate while assembling a uniqueness proof from localization + descent (e.g. bans on placeholder interfaces, requirements on where hypotheses may live)?
Report verbatim quotes for the binding clauses with page numbers. Your final message is consumed by another agent as raw data.`,
  },
]

const results = await parallel(readers.map(r => () =>
  agent(r.prompt, { label: `read:${r.key}`, phase: 'Map', schema: SCHEMA, model: 'opus' })
    .then(res => ({ key: r.key, ...res }))
))

return { results: results.filter(Boolean) }

